SELL_CARRY_DAYS = 3

#: `shedCapacity`, the ONE limit shared by all nine products (`reference/kaggriculture.py:835`).
SHED_CAPACITY = 100

#: Whether a sale may exceed the schedule's row purely to keep room for tonight's dusk drop.
